-- Read-only reconciliation, executed 2026-10-31. Not a seed/migration or production write.
-- DATETIME columns use the application's JDBC UTC+07 mapping; stored JSON instants are UTC.
select '2026-10-31T07:16:02Z' as as_of_utc,'Asia/Ho_Chi_Minh' as timezone;
select period,(select count(*) from bookings b join user_accounts u on u.id=b.customer_id join suppliers s on s.id=b.supplier_id where u.role='CUSTOMER' and s.demo_data=false and b.created_at>=periods.start_at and b.created_at<periods.end_at) as operational_bookings,(select count(*) from presentation_recovery pr, json_table(pr.payload,'$.data.bookings[*]' columns(created varchar(50) path '$.createdAt')) j where date_add(str_to_date(left(replace(j.created,'T',' '),19),'%Y-%m-%d %H:%i:%s'),interval 7 hour)>=periods.start_at and date_add(str_to_date(left(replace(j.created,'T',' '),19),'%Y-%m-%d %H:%i:%s'),interval 7 hour)<periods.end_at) as stored_bookings,(select count(*) from user_accounts u where u.created_at<periods.end_at) as operational_cumulative_users,(select count(*) from presentation_recovery pr,json_table(pr.payload,'$.data.users[*]' columns(created varchar(50) path '$.createdAt')) j where date_add(str_to_date(left(replace(j.created,'T',' '),19),'%Y-%m-%d %H:%i:%s'),interval 7 hour)<periods.end_at) as stored_cumulative_users from (select 'current' as period,cast('2026-10-02 00:00:00' as datetime) as start_at,cast('2026-10-31 14:16:02' as datetime) as end_at union all select 'previous','2026-09-02 00:00:00','2026-10-01 14:16:02') periods;
select period,(select coalesce(sum(p.amount),0) from payment_transactions p join bookings b on b.id=p.booking_id join user_accounts u on u.id=b.customer_id join suppliers s on s.id=b.supplier_id where u.role='CUSTOMER' and s.demo_data=false and p.status='PAID' and p.requires_manual_review=false and p.paid_at>=periods.start_at and p.paid_at<periods.end_at and p.id=(select min(p2.id) from payment_transactions p2 where p2.booking_id=p.booking_id and p2.status='PAID')) as verified_gross,(select count(*) from bookings b join user_accounts u on u.id=b.customer_id join suppliers s on s.id=b.supplier_id where u.role='CUSTOMER' and s.demo_data=false and b.created_at>=periods.start_at and b.created_at<periods.end_at and exists(select 1 from payment_transactions p where p.booking_id=b.id and p.status='PAID' and p.requires_manual_review=false and p.paid_at is not null and p.paid_at<periods.end_at and p.id=(select min(p2.id) from payment_transactions p2 where p2.booking_id=p.booking_id and p2.status='PAID'))) as paid_booking_numerator from (select 'current' as period,cast('2026-10-02 00:00:00' as datetime) as start_at,cast('2026-10-31 14:16:02' as datetime) as end_at union all select 'previous','2026-09-02 00:00:00','2026-10-01 14:16:02') periods;
select count(*) as transactions,sum(status='PAID') as paid,sum(case when status='PAID' and paid_at is not null and requires_manual_review=false then amount else 0 end) as paid_amount from payment_transactions;
